<?php
declare(strict_types=1);

function qa180_coupon_amount(array $coupon,array $lines):int {
    if(!$coupon['is_active']||($coupon['starts_at']&&strtotime($coupon['starts_at'])>time())||($coupon['ends_at']&&strtotime($coupon['ends_at'])<time()))throw new DomainException('El código no está activo o vigente.');
    if($coupon['max_uses']!==null&&(int)$coupon['uses_count']>=(int)$coupon['max_uses'])throw new DomainException('El código alcanzó su límite de usos.');
    $products=array_map('intval',json_decode((string)$coupon['applicable_products'],true)?:[]);$categories=array_map('intval',json_decode((string)$coupon['applicable_categories'],true)?:[]);$eligible=0;$subtotal=0;
    foreach($lines as $line){$net=pos_cents_148($line['subtotal']);$subtotal+=$net;$p=$line['product'];if((!$products&&!$categories)||in_array((int)$p['id'],$products,true)||in_array((int)$p['category_id'],$categories,true))$eligible+=$net;}
    if($subtotal<pos_cents_148($coupon['min_order']))throw new DomainException('Compra mínima: '.money((float)$coupon['min_order']).'.');if($eligible<=0)throw new DomainException('El código no aplica a los productos de esta cuenta.');
    return $coupon['type']==='percent'?min($eligible,(int)round($eligible*(float)$coupon['value']/100)):min($eligible,pos_cents_148($coupon['value']));
}
function qa180_coupon_find(App $app,array $tenant,string $code,array $lines,bool $lock=false):array {
    $coupon=$app->one('SELECT * FROM coupons WHERE tenant_id=? AND code=?'.($lock?' FOR UPDATE':''),[$tenant['id'],strtoupper(trim($code))]);if(!$coupon)throw new DomainException('Código no disponible.');return [$coupon,qa180_coupon_amount($coupon,$lines)];
}
function qa180_coupon_record(App $app,array $tenant,array $coupon,string $key,int $amount,?int $order=null,?int $sale=null,?int $ticket=null):void {
    if(!$app->db->inTransaction())throw new LogicException('El uso del código requiere una transacción.');$old=$app->one('SELECT id FROM fisitaap_coupon_uses180 WHERE tenant_id=? AND coupon_id=? AND operation_key=?',[$tenant['id'],$coupon['id'],$key]);if($old)return;
    $app->exec('INSERT INTO fisitaap_coupon_uses180(tenant_id,coupon_id,operation_key,order_id,sale_id,ticket_id,amount) VALUES(?,?,?,?,?,?,?)',[$tenant['id'],$coupon['id'],$key,$order,$sale,$ticket,$amount/100]);$app->exec('UPDATE coupons SET uses_count=uses_count+1 WHERE id=? AND tenant_id=?',[$coupon['id'],$tenant['id']]);
}
function qa180_coupons(App $app,array $user,array $tenant):void {
    $id=(int)($_GET['edit']??$_POST['id']??0);$coupon=$id?$app->one('SELECT * FROM coupons WHERE id=? AND tenant_id=?',[$id,$tenant['id']]):null;if($id&&!$coupon)throw new DomainException('Código no disponible.');
    if(is_post()){
        verify_csrf();qa180_permission($app,$user,'promociones','write');try{
            $code=strtoupper(trim((string)($_POST['code']??'')));$type=($_POST['type']??'')==='fixed'?'fixed':'percent';$value=r2_number($_POST['value']??0,.01,$type==='percent'?100:999999999);$minimum=r2_number($_POST['min_order']??0);$max=trim((string)($_POST['max_uses']??''));if(!preg_match('/^[A-Z0-9_-]{2,60}$/D',$code)||str_starts_with($code,'FIEL-'))throw new DomainException('Usa letras, números, guion o guion bajo. FIEL- está reservado para premios.');if($max!==''&&(!ctype_digit($max)||(int)$max<1||(int)$max>100000000))throw new DomainException('El límite de usos debe ser un entero positivo o quedar vacío.');
            $dates=[];foreach(['starts_at','ends_at'] as $field){$raw=trim((string)($_POST[$field]??''));$at=$raw!==''?strtotime($raw):null;if($raw!==''&&$at===false)throw new DomainException('Revisa las fechas del código.');$dates[]=$at?date('Y-m-d H:i:s',$at):null;}if($dates[0]&&$dates[1]&&$dates[0]>$dates[1])throw new DomainException('El fin debe ser posterior al inicio.');
            $ids=[];foreach(['products'=>'products','categories'=>'categories'] as $field=>$table){$selected=array_values(array_unique(array_filter(array_map('intval',(array)($_POST[$field]??[])))));if(count($selected)>1000)throw new DomainException('Selecciona hasta 1000 elementos.');if($selected){$marks=implode(',',array_fill(0,count($selected),'?'));if(count($app->all('SELECT id FROM '.$table.' WHERE tenant_id=? AND id IN('.$marks.')',[$tenant['id'],...$selected]))!==count($selected))throw new DomainException('Un producto o categoría pertenece a otro negocio.');}$ids[$field]=json_encode($selected,JSON_THROW_ON_ERROR);}
            $values=[$code,$type,$value,$minimum,$max===''?null:(int)$max,...$dates,isset($_POST['is_active'])?1:0,$ids['products'],$ids['categories']];
            if($id)$app->exec('UPDATE coupons SET code=?,type=?,value=?,min_order=?,max_uses=?,starts_at=?,ends_at=?,is_active=?,applicable_products=?,applicable_categories=? WHERE id=? AND tenant_id=?',[...$values,$id,$tenant['id']]);else{$app->exec('INSERT INTO coupons(code,type,value,min_order,max_uses,starts_at,ends_at,is_active,applicable_products,applicable_categories,tenant_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[...$values,$tenant['id']]);$id=(int)$app->db->lastInsertId();}
            qa180_audit($app,$user,'coupon_save','coupon',$id,'Configuró el código '.$code);flash('success','Código guardado. La aplicación valida los productos y usos al confirmar.');redirect(url('admin/cupones'));
        }catch(Throwable $error){flash('error',$error instanceof PDOException?'No se guardó el código. Revisa si ya existe.':$error->getMessage());redirect(url('admin/cupones'.($id?'?edit='.$id:'')));}
    }
    $products=$app->all('SELECT id,name FROM products WHERE tenant_id=? ORDER BY name',[$tenant['id']]);$categories=$app->all('SELECT id,name FROM categories WHERE tenant_id=? ORDER BY name',[$tenant['id']]);admin_shell_start('Códigos de descuento',$user,$tenant,'promociones');echo '<section class="card admin-card"><h2>'.($coupon?'Editar código':'Crear código').'</h2><p>Elige productos o categorías. Sin selección se aplica a todo el catálogo. Los límites se comprueban al confirmar; cada pedido o cuenta usa el código una vez.</p><form method="post">'.csrf_field().pos_hidden_148('id',$id).field('Código','code',$coupon['code']??'',true).'<label>Tipo<select class="input" name="type"><option value="percent">Porcentaje</option><option value="fixed" '.(($coupon['type']??'')==='fixed'?'selected':'').'>Monto fijo</option></select></label>'.field('Valor','value',$coupon['value']??10,true,'number','.01').field('Compra mínima','min_order',$coupon['min_order']??0,false,'number','.01').field('Máximo de usos (vacío = sin límite)','max_uses',$coupon['max_uses']??'',false,'number','1').field('Inicio','starts_at',isset($coupon['starts_at'])?str_replace(' ','T',substr($coupon['starts_at'],0,16)):'',false,'datetime-local').field('Fin','ends_at',isset($coupon['ends_at'])?str_replace(' ','T',substr($coupon['ends_at'],0,16)):'',false,'datetime-local');
    foreach(['products'=>['Productos',$products],'categories'=>['Categorías',$categories]] as $field=>[$label,$rows]){$selected=array_map('intval',json_decode((string)($coupon['applicable_'.$field]??'[]'),true)?:[]);echo '<label>'.e($label).'<select class="input" name="'.$field.'[]" multiple size="6" data-searchable-select>';foreach($rows as $row)echo '<option value="'.$row['id'].'" '.(in_array((int)$row['id'],$selected,true)?'selected':'').'>'.e($row['name']).'</option>';echo '</select></label>';}
    echo '<label><input type="checkbox" name="is_active" '.(($coupon['is_active']??1)?'checked':'').'> Activo</label><button class="btn">Guardar código</button> <a class="btn btn-light" href="'.e(url('admin/promociones')).'">Precios especiales y 2 × 1</a></form></section><section class="card admin-card"><h2>Códigos existentes</h2><div class="table-wrap"><table class="table"><thead><tr><th>Código</th><th>Descuento</th><th>Usos</th><th>Estado</th><th></th></tr></thead><tbody>';foreach($app->all('SELECT * FROM coupons WHERE tenant_id=? ORDER BY id DESC',[$tenant['id']]) as $row)echo '<tr><td>'.e($row['code']).'</td><td>'.($row['type']==='percent'?e($row['value']).'%':money((float)$row['value'])).'</td><td>'.(int)$row['uses_count'].' / '.e($row['max_uses']??'Sin límite').'</td><td>'.($row['is_active']?'Activo':'Inactivo').'</td><td><a href="'.e(url('admin/cupones?edit='.(int)$row['id'])).'">Editar</a></td></tr>';echo '</tbody></table></div></section>';admin_shell_end();
}
function qa180_coupon_preview(App $app):never {
    $raw=json_input_qa();$_POST=$raw+$_POST;verify_csrf();$tenant=tenant_by_slug($app,(string)($raw['tenant']??''));if(!$tenant||!$tenant['is_active'])json_response(['ok'=>false,'error'=>'Negocio no disponible.'],404);
    $code=strtoupper(trim((string)($raw['coupon']??'')));if(str_starts_with($code,'FIEL-'))json_response(['ok'=>true,'valid'=>null,'discount'=>0,'message'=>'El premio se valida al confirmar el pedido.']);
    try{
        $items=(array)($raw['items']??[]);if(!$items||count($items)>100)throw new DomainException('Agrega productos para comprobar el código.');$ids=array_values(array_unique(array_map(fn($item)=>(int)($item['id']??0),$items)));$marks=implode(',',array_fill(0,count($ids),'?'));$bid=(int)($raw['branch_id']??0);$branch=$bid?$app->one('SELECT id FROM branches WHERE id=? AND tenant_id=? AND is_active=1',[$bid,$tenant['id']]):$app->one('SELECT id FROM branches WHERE tenant_id=? AND is_active=1 ORDER BY is_default DESC,id LIMIT 1',[$tenant['id']]);if(!$branch)throw new DomainException('Selecciona una sucursal activa.');
        $rows=$app->all('SELECT p.*,bp.is_active branch_active,bp.price_override,bp.sale_price_override FROM products p LEFT JOIN branch_products bp ON bp.product_id=p.id AND bp.branch_id=? WHERE p.tenant_id=? AND p.status<>"hidden" AND p.id IN('.$marks.')',[$branch['id'],$tenant['id'],...$ids]);$products=[];foreach($rows as $p){if($tenant['catalog_mode']==='branches'){if(!$p['branch_active'])continue;$p['price']=$p['price_override']??$p['price'];$p['sale_price']=$p['sale_price_override']??$p['sale_price'];}$products[(int)$p['id']]=$p;}
        $lines=[];foreach($items as $item){$p=$products[(int)($item['id']??0)]??null;if(!$p)throw new DomainException('Un producto ya no está disponible.');$quantity=r2_number($item['qty']??0,(float)$p['min_qty'],99999);if(abs(($quantity-(float)$p['min_qty'])/(float)$p['qty_step']-round(($quantity-(float)$p['min_qty'])/(float)$p['qty_step']))>.0001)throw new DomainException('Revisa la cantidad del producto.');$options=pos_product_options_v141($app,(int)$tenant['id'],(int)$p['id'],array_values(array_unique(array_map('intval',(array)($item['option_ids']??[])))));$priced=r2_line($app,$tenant,$p,$quantity,$options['price']);$lines[]=['product'=>$p,'subtotal'=>$priced['subtotal']];}
        [$coupon,$amount]=qa180_coupon_find($app,$tenant,$code,$lines);json_response(['ok'=>true,'valid'=>true,'discount'=>$amount/100,'code'=>$coupon['code'],'message'=>'Código válido: descuento '.money($amount/100).' en los productos aplicables.']);
    }catch(DomainException $error){json_response(['ok'=>true,'valid'=>false,'discount'=>0,'message'=>$error->getMessage()]);}
}
function qa180_coupon_ticket_lines(App $app,int $ticket):array {
    $lines=[];foreach($app->all('SELECT i.id,i.product_id,i.line_subtotal,p.category_id FROM pos_ticket_items i LEFT JOIN products p ON p.id=i.product_id WHERE i.ticket_id=? ORDER BY i.id',[$ticket]) as $item)$lines[]=['item_id'=>(int)$item['id'],'product'=>['id'=>(int)$item['product_id'],'category_id'=>(int)$item['category_id']],'subtotal'=>$item['line_subtotal']];return $lines;
}
function qa180_coupon_apply(App $app,array $tenant,array $user,array $ticket,string $code):void {
    qa180_permission($app,$user,'ventas','write');$code=strtoupper(trim($code));
    if($code===''){$app->exec('UPDATE pos_tickets SET coupon_id=NULL,discount_total=0 WHERE id=? AND tenant_id=?',[$ticket['id'],$tenant['id']]);return;}
     $lines=qa180_coupon_ticket_lines($app,(int)$ticket['id']);[$coupon,$amount]=qa180_coupon_find($app,$tenant,$code,$lines,true);qa180_coupon_store_allocation($app,(int)$ticket['id'],qa180_coupon_allocate($coupon,$lines,$amount));$app->exec('UPDATE pos_tickets SET coupon_id=?,discount_total=? WHERE id=? AND tenant_id=?',[$coupon['id'],$amount/100,$ticket['id'],$tenant['id']]);
}
function qa180_coupon_refresh(App $app,array $ticket):void {
    if(!$ticket['coupon_id']||!empty($ticket['source_order_id']))return;
    if($app->one('SELECT id FROM pos_ticket_items WHERE ticket_id=? AND paid_quantity>0 LIMIT 1',[$ticket['id']]))return;
    $coupon=$app->one('SELECT * FROM coupons WHERE id=? AND tenant_id=?',[$ticket['coupon_id'],$ticket['tenant_id']]);
    try{if(!$coupon)throw new DomainException('Código eliminado.');$lines=qa180_coupon_ticket_lines($app,(int)$ticket['id']);$amount=qa180_coupon_amount($coupon,$lines);qa180_coupon_store_allocation($app,(int)$ticket['id'],qa180_coupon_allocate($coupon,$lines,$amount));$app->exec('UPDATE pos_tickets SET discount_total=? WHERE id=?',[$amount/100,$ticket['id']]);}
    catch(DomainException){$app->exec('UPDATE pos_tickets SET coupon_id=NULL,discount_total=0 WHERE id=?',[$ticket['id']]);flash('info','Se quitó el código porque la cuenta cambió o ya no cumple sus condiciones. Puedes aplicar otro código vigente.');}
}
function qa180_coupon_settlement(App $app,array $tenant,array $tickets,int $sale):void {
    foreach($tickets as $ticket){if(!$ticket['coupon_id'])continue;$coupon=$app->one('SELECT * FROM coupons WHERE id=? AND tenant_id=? FOR UPDATE',[$ticket['coupon_id'],$tenant['id']]);if(!$coupon)throw new DomainException('Código no disponible.');
        $key='ticket-'.$ticket['id'];$use=$app->one('SELECT id FROM fisitaap_coupon_uses180 WHERE tenant_id=? AND coupon_id=? AND operation_key=?',[$tenant['id'],$coupon['id'],$key]);if($use)continue;
        if($ticket['source_order_id']){$orderUse=$app->one('SELECT id FROM fisitaap_coupon_uses180 WHERE tenant_id=? AND coupon_id=? AND order_id=?',[$tenant['id'],$coupon['id'],$ticket['source_order_id']]);if($orderUse){$app->exec('UPDATE fisitaap_coupon_uses180 SET ticket_id=?,sale_id=COALESCE(sale_id,?) WHERE id=?',[$ticket['id'],$sale,$orderUse['id']]);continue;}}
        $lines=qa180_coupon_ticket_lines($app,(int)$ticket['id']);$amount=qa180_coupon_amount($coupon,$lines);$allocation=qa180_coupon_allocate($coupon,$lines,$amount);foreach($app->all('SELECT id,pricing_json FROM pos_ticket_items WHERE ticket_id=?',[$ticket['id']]) as $item)if((int)(json_decode((string)$item['pricing_json'],true)['coupon_discount180']??-1)!==(int)($allocation[$item['id']]??0))throw new DomainException('Los productos aplicables del código cambiaron. Vuelve a aplicarlo antes de cobrar.');if($amount!==pos_cents_148($ticket['discount_total']))throw new DomainException('El código o sus productos cambiaron. Revisa el descuento actualizado antes de cobrar.');qa180_coupon_record($app,$tenant,$coupon,$key,$amount,null,$sale,(int)$ticket['id']);
    }
}
function qa180_coupon_allocate(array $coupon,array $lines,int $amount):array {
    $products=array_map('intval',json_decode((string)$coupon['applicable_products'],true)?:[]);$categories=array_map('intval',json_decode((string)$coupon['applicable_categories'],true)?:[]);$weights=[];
    foreach($lines as $index=>$line){$p=$line['product'];$eligible=(!$products&&!$categories)||in_array((int)$p['id'],$products,true)||in_array((int)$p['category_id'],$categories,true);$weights[$line['item_id']??$index]=$eligible?pos_cents_148($line['subtotal']):0;}
    return pos_allocate_148($amount,$weights);
}
function qa180_coupon_store_allocation(App $app,int $ticket,array $allocation):void {
    foreach($app->all('SELECT id,pricing_json FROM pos_ticket_items WHERE ticket_id=? ORDER BY id',[$ticket]) as $item){$recipe=json_decode((string)$item['pricing_json'],true)?:[];$recipe['coupon_discount180']=(int)($allocation[$item['id']]??0);$app->exec('UPDATE pos_ticket_items SET pricing_json=? WHERE id=?',[json_encode($recipe,JSON_THROW_ON_ERROR),$item['id']]);}
}
